/**
* Script to regenerate namespace_segments.json from current stdlib namespaces.
*
* ## Usage
*
* ```bash
* node scripts/build.js
* ```
*/

'use strict';

/* eslint-disable no-console, node/no-sync */

// MODULES //

var resolve = require( 'path' ).resolve;
var writeFileSync = require( 'fs' ).writeFileSync;
var objectKeys = require( '@stdlib/utils/keys' );
var namespaces = require( '@stdlib/_tools/pkgs/namespaces' ).sync;


// VARIABLES //

var OUTPUT_PATH = resolve( __dirname, '..', 'lib', 'namespace_segments.json' );


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var segments;
	var names;
	var parts;
	var json;
	var i;
	var j;

	console.log( 'Fetching stdlib namespaces...' );
	names = namespaces();

	console.log( 'Found %d namespaces.', names.length );

	// Extract unique namespace segments:
	segments = {};
	for ( i = 0; i < names.length; i++ ) {
		// Remove @stdlib/ prefix and split into segments:
		parts = names[ i ].replace( '@stdlib/', '' ).split( '/' );
		for ( j = 0; j < parts.length; j++ ) {
			// Exclude internal tools (starting with underscore):
			if ( parts[ j ].charAt( 0 ) !== '_' ) {
				segments[ parts[ j ] ] = true;
			}
		}
	}
	segments = objectKeys( segments ).sort();

	console.log( 'Extracted %d unique namespace segments.', segments.length );

	// Write to JSON file:
	json = JSON.stringify( segments, null, '  ' ) + '\n';
	writeFileSync( OUTPUT_PATH, json );

	console.log( 'Written to: %s', OUTPUT_PATH );
}

main();
